/* Reviewed evidence summaries. Same source packet used by the UI and server. */
(function(root){'use strict';
const cards={
 downtime:{title:'Does a broken machine lose money for the whole casino?',answer:'Same-game, location and hour comparisons estimate $102,216 of machine-level expected house win forgone across January–June. If half the play stayed on other machines, the property-level estimate falls to $51,108; if all stayed, it is zero.',challenge:'Customer switching was not observed. Similar machines may already absorb displaced demand, and some sparse comparison cells use broader locations. This is a modeled opportunity loss, not measured lost profit.',measure:'Compare repaired machines with same-game peers and track whole-property contribution after costs. Change the switching assumption from zero to full retention before funding repairs.',source:'Claims appendix: advanced_analysis.py matchedDowntime; machine_hour, game math, dated placements.',href:'evidence/CLAIMS_AND_EVIDENCE.md',desk:'operations'},
 guests:{title:'What happened to tracked players?',answer:'Loyalty-card player records show about $163.8 million wagered and $148.2 million paid back. About 16.4% of player-months finished ahead. The top 10% ranked by six-month expected loss account for 63.8% of tracked expected loss.',challenge:'These are carded players only, not everyone on the floor. A player-month is not a unique person. The concentration ranking uses the full six months and does not prove future behavior.',measure:'Use guest-region and tier filters to inspect cohorts, keeping the full-period concentration scope explicit. Reconcile carded meters separately; never target people losing heavily to encourage more gambling.',source:'Claims appendix: analysis.py C8–C10; player_period and carded machine meters.',href:'evidence/CLAIMS_AND_EVIDENCE.md',desk:'guests'},
 loyalty:{title:'Did the loyalty program change?',answer:'Points per comp dollar fell from roughly 12.5 to 5.8 in late April. January–June redemptions cost $190,669.30. Reinvestment was roughly 1.2% before and 1.3% after. Comp cost is already included in cost of goods sold.',challenge:'This pricing change is descriptive, not evidence of extra play or profit. Subtracting comp cost again would double-count it. Carded activity does not represent all guests.',measure:'The optional pilot is deferred, not funded: 10,288 assigned players per arm, a $4.88 detectable effect at 80% power under the stated assumptions. Include non-returners and judge contribution after costs, with welfare and stop rules.',source:'Claims appendix: analysis.py C11–C12 and pilot; loyalty_ledger, property_day; PILOT_PROTOCOL.md.',href:'evidence/CLAIMS_AND_EVIDENCE.md',desk:'guests'},
 budget:{title:'Why keep most of the $100,000?',answer:'Fund one $1,200 inspection of M-1158 and reserve $98,800. Conditional inspection-plan net outcomes are about -$1,224 with no recovery, +$276 with $3,000 recovery and $1,500 repair, or +$3,276 with $6,000 recovery and $1,500 repair. These include modeled downtime.',challenge:'The recovery amounts are assumptions, not predictions or probabilities. Inspection may find nothing. The larger three-action package has a negative base outcome; catalogue prices do not establish benefits.',measure:'First verify a fault. Require a repair quote and a separate spending decision. Track property-wide contribution after costs against comparable machines and stop escalation if no fault or viable repair is found.',source:'Claims appendix: scenarios and accounting; action_catalog, cost_rules; inspection measurement plan.',href:'evidence/CLAIMS_AND_EVIDENCE.md',desk:'plan'},

 inspect:{title:'Why inspect instead of replacing?',answer:'M-1158 paid on 38.57% of spins versus 31.54% in its published game settings. That discrepancy warrants checking its meters and configuration. A $1,200 inspection buys information before committing $22,000 to replace that one machine. Neither action has a proven recovery benefit.',challenge:'A wrong published configuration, meter error or dependence between spins could explain the signal. It is not proof of a defective machine or wrongdoing. Inspection may find nothing.',measure:'First reconcile the meters and configured paytable. If no fault is verified, keep monitoring rather than automatically replacing it. Any repair needs a separate quote and decision within the reserve. After an intervention, compare availability and expected win per available hour with same-game peers, and track whole-property contribution after costs.',source:'Claims appendix: M-1158 / analysis.py C3; game_math, machine meters and action_catalog.',href:'evidence/CLAIMS_AND_EVIDENCE.md',desk:'brief'},
 location:{title:'Did moving machines work?',answer:'Of four movers, M-1152 showed a +130.4% relative change in expected win per available hour compared with same-game source-zone stayers. The pointwise interval was +105.7% to +160.9%. The other three intervals include no change.',challenge:'Moves were not randomized and comparison groups were small. Customer switching is possible but was not measured. The study does not establish new casino-wide profit. Back Forty was already declining before the closure, weakening a simple closure-causation story.',measure:'Treat this as a reason to test placement, not to move every machine. Pre-specify comparison machines, check pre-move trends, and measure property-wide effects as well as the destination zone.',source:'Claims appendix: advanced_analysis.py movers and pretrend; dated placements.',href:'evidence/CLAIMS_AND_EVIDENCE.md',desk:'movers'},
 model:{title:'What does the model change?',answer:'The January–April weekday model had May–June average absolute error of $68,699, compared with $218,258 for a constant baseline. It informs when to schedule disruptive work; it does not predict the benefit of inspection.',challenge:'A better wager forecast is not a treatment-effect model. Earlier rolling checks help, but temporal dependence and demand changes limit interval guarantees.',measure:'Keep the May–June test labeled as the original holdout. Schedule after action lead time, confirm staffing, and monitor forecast error on genuinely new periods.',source:'Claims appendix: forecast, rolling checks and decision.js scheduling.',href:'evidence/CLAIMS_AND_EVIDENCE.md',desk:'forecast'}
};
function get(topic){if(!Object.hasOwn(cards,topic))throw Error('Unknown evidence topic');return JSON.parse(JSON.stringify(cards[topic]));}
root.AceEvidenceCards={get,topics:Object.keys(cards)};if(typeof module!=='undefined')module.exports=root.AceEvidenceCards;
})(typeof window==='undefined'?globalThis:window);
